# Fix: Remove try/except blocks. Instead, use AI assistant to extract price for all hotels, and only keep those with valid float prices <= 210.

class HotelPriceExtract(BaseModel):
    price: float

def extract_price_or_none(name, price_str):
    # Use AI assistant to extract price, return None if not possible
    try_float = False
    if price_str.replace('.', '', 1).isdigit():
        try_float = True
    if try_float:
        price = float(price_str)
        return price
    else:
        try:
            price_obj = query_ai_assistant(
                f"Extract the numeric price per night from this string: '{price_str}'. If not a valid price, raise an error.",
                HotelPriceExtract
            )
            return price_obj.price
        except Exception:
            return None

affordable_hotels = []
for name in hotel_names:
    price_str = hotel_prices.get(name, "")
    # Only process if price_str is not empty
    if price_str.strip() != "":
        # Use AI assistant to extract price, skip if not possible
        price = None
        if price_str.replace('.', '', 1).isdigit():
            price = float(price_str)
        else:
            try:
                price_obj = query_ai_assistant(
                    f"Extract the numeric price per night from this string: '{price_str}'. If not a valid price, raise an error.",
                    HotelPriceExtract
                )
                price = price_obj.price
            except Exception:
                price = None
        if price is not None and price <= 210:
            affordable_hotels = [*affordable_hotels, name]

# Continue with the rest of the code as before

hotel_ratings = get_rating_reviews_for_hotels(affordable_hotels)

class HotelRating(BaseModel):
    name: str
    rating: float

hotel_rating_objs = [
    query_ai_assistant(
        f"Extract the hotel name and its rating from this review: {hotel_ratings[name]} for hotel {name}.",
        HotelRating
    )
    for name in affordable_hotels
]

if len(hotel_rating_objs) == 0:
    raise ValueError("No hotels found within the budget.")
best_hotel = sorted(hotel_rating_objs, key=lambda x: x.rating, reverse=True)[0].name

restaurants_str = get_all_restaurants_in_city("Paris")
restaurant_names = restaurants_str.splitlines()

cuisine_types = get_cuisine_type_for_restaurants(restaurant_names)
french_restaurants = [name for name in restaurant_names if "french" in cuisine_types.get(name, "").lower()]

opening_hours = check_restaurant_opening_hours(french_restaurants)

class OpenOnSundayLunch(BaseModel):
    open_for_lunch: bool

open_sunday_lunch = [
    name for name in french_restaurants
    if query_ai_assistant(
        f"Does this restaurant's opening hours indicate it is open for lunch on Sunday? Opening hours: {opening_hours[name]}",
        OpenOnSundayLunch
    ).open_for_lunch
]

restaurant_ratings = get_rating_reviews_for_restaurants(open_sunday_lunch)

class RestaurantRating(BaseModel):
    name: str
    rating: float

restaurant_rating_objs = [
    query_ai_assistant(
        f"Extract the restaurant name and its rating from this review: {restaurant_ratings[name]} for restaurant {name}.",
        RestaurantRating
    )
    for name in open_sunday_lunch
]

if len(restaurant_rating_objs) == 0:
    raise ValueError("No French restaurants open for lunch on Sunday found.")
best_restaurant = sorted(restaurant_rating_objs, key=lambda x: x.rating, reverse=True)[0].name

hotel_price_per_night = float(hotel_prices[best_hotel])
restaurant_prices = get_price_for_restaurants([best_restaurant])
restaurant_price_per_person = float(restaurant_prices[best_restaurant])

hotel_total = hotel_price_per_night * 3
meals_total = restaurant_price_per_person * 2 * 3
total_cost = hotel_total + meals_total

print(
    "Hotel recommendation: {}\nRestaurant recommendation: {}\nEstimated minimum cost for the trip: {:.2f}".format(
        best_hotel, best_restaurant, total_cost
    )
)
